const icons={Compass,Feather,Hammer,ChartNoAxesCombined,Zap,Gem,Radio,MessagesSquare,Swords,HeartHandshake,Settings,Crown,Map,ScrollText,ShieldCheck,BookOpen,UserRound,Lock,ArrowRight,Check,Flame,Shield,KeyRound,Star,Download,LogOut,Volume2,VolumeX,ChevronRight,ExternalLink,Cloud,HardDrive,RefreshCw};
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,cls='')=>`<i data-lucide="${name}" class="${cls}" aria-hidden="true"></i>`;
let state=api.session,selectedWorld=0,selectedMission='m1',selectedGuide='strategist',busy=false,installPrompt=null,queue=[],vaultFilter='all';
let prefs;try{prefs=JSON.parse(localStorage.getItem('oyo-preferences')||'{}')}catch{prefs={}};
let communityMessages=[],communityStop=null,communityUid=null,communityReports=[];
let adminOverview=null;
let bankItems=[],bankLoaded=false,bankFilter='all',bankURLs=[],bankExport=null;
function clearBankURLs(){for(const url of bankURLs)URL.revokeObjectURL(url);bankURLs=[];}
function bankImage(item){const url=URL.createObjectURL(new Blob([item.image],{type:'image/jpeg'}));bankURLs.push(url);return url;}
async function reloadBank(){bankItems=await api.loadBank();bankLoaded=true;render();}
let hydrated=false;
let view=location.hash.slice(1)||'map';
const routes=['map','unlocked','mission','guides','boss','vault','progress','resources','membership','profile','review','community','admin'];
if(!routes.includes(view))view='map';
function go(next){location.hash=next;if(view===next)render();}
window.addEventListener('hashchange',()=>{view=routes.includes(location.hash.slice(1))?location.hash.slice(1):'map';render();$('#main')?.focus();});
window.addEventListener('oyo-error',e=>notify(e.detail,true));
window.addEventListener('online',()=>render());window.addEventListener('offline',()=>render());
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;render();});
function notify(text,error=false){const n=$('#notice');n.textContent=text;n.className=error?'show error':'show';clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.className='',6500);}
function sound(){if(!prefs.sound)return;try{const c=new (window.AudioContext||window.webkitAudioContext)();const o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.setValueAtTime(523,c.currentTime);o.frequency.setValueAtTime(784,c.currentTime+.12);g.gain.setValueAtTime(.04,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.4);o.start();o.stop(c.currentTime+.4);o.onended=()=>c.close();}catch{}}
async function run(fn){if(busy)return;busy=true;document.body.classList.add('busy');document.body.setAttribute('aria-busy','true');try{await fn();}catch(e){notify(e.code==='resource-exhausted'?'Game storage or today’s free usage allowance is full. Nothing was saved. Save to your phone or device and try again later.':e.message||'Something went wrong. Try again.',true);}finally{busy=false;document.body.classList.remove('busy');document.body.removeAttribute('aria-busy');}}
const portrait=(index,row=0)=>`<span class="character-art" style="--portrait-x:${index*20}%;--portrait-y:${row*100}%" aria-hidden="true"></span>`;
const currentMission=()=>missions.find(m=>missionOpen(state.game,m.id)&&missionState(state.game,m.id).status!=='verified');
function nav(label,id,symbol){return `<button class="nav-item ${view===id?'active':''}" aria-label="${label}" data-nav="${id}" ${view===id?'aria-current="page"':''}>${icon(symbol)}<span>${label}</span>${view===id?icon('ChevronRight'):''}</button>`;}
function title(kicker,text,extra=''){return `<header class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${text}</h1></div>${extra}</header>`;}
function render(){const g=state.game;document.documentElement.dataset.aura=g.cosmetics?.aura||'violet';document.documentElement.classList.toggle('reduce-motion',!!prefs.motion);$('#app').innerHTML=`
 <aside class="sidebar"><a class="brand" href="#map" aria-label="OYO Unlocked world map">${icon('Crown')}<strong>OYO</strong><span>UNLOCKED</span><small>OWN YOUR OPTIONS</small></a>
 <button class="player" data-nav="profile"><span class="avatar player-portrait" aria-hidden="true"></span><span><b>${esc(g.profile.name)}</b><small class="player-title">${esc(g.cosmetics?.title||'New arrival')}</small><small>Level ${level(g)} · ${esc(g.profile.path)}</small></span></button>
 <nav aria-label="Game navigation">${nav('World map','map','Map')}${nav('UNLOCKED','unlocked','Gem')}${nav('Missions','mission','ScrollText')}${nav('Guides','guides','Compass')}${nav('Boss battles','boss','Swords')}${nav('Submitted Proof','vault','ShieldCheck')}${nav('Community','community','MessagesSquare')}${nav('Skill tree','progress','ChartNoAxesCombined')}<div class="nav-divider"></div>${nav('Proof Bank','resources','BookOpen')}${nav('Membership','membership','Crown')}${nav('Character & settings','profile','Settings')}${state.isOwner?nav('Owner Admin','admin','Shield'):''}</nav>
 <div class="sidebar-foot"><span class="save-badge">${icon(api.cloud?'Cloud':'HardDrive')}${api.cloud?(state.user?'Cloud adventure':'Sign in to save'):'Saved on this device'}</span><p>Real skills.<br>More possibilities.</p><small>THE UNWRITTEN REACH · v0.6</small></div></aside>
 <div class="game-shell"><header class="hud"><div class="location">${icon('Compass')}<span>YOUR ADVENTURE <b>${esc(worlds[selectedWorld].name)}</b></span></div><div class="xp-hud"><span>LEVEL ${level(g)}</span><div><div class="xp-label"><b>${g.xp%500} / 500 XP</b><small>NEXT LEVEL</small></div><progress max="500" value="${g.xp%500}" aria-label="Experience toward next level"></progress></div></div><div class="hud-stat">${icon('Zap')}<b>${Object.values(g.skills).reduce((a,b)=>a+b,0)}</b><small>SKILLS</small></div><div class="hud-stat gold">${icon('KeyRound')}<b>${g.options.length}</b><small>OPTIONS</small></div><button class="icon-button" data-nav="profile" aria-label="Character and settings">${icon('UserRound')}</button></header>
 ${!navigator.onLine?'<div class="mode-banner">Offline · '+(api.cloud?'Your cloud adventure needs a connection.':'Your device adventure remains available. Live services need internet.')+'</div>':''}
 ${api.cloud&&!state.user?'<div class="mode-banner">Sign in to begin your cloud adventure. <button data-nav="profile">Open account</button></div>':''}
 ${!state.ready?`<div class="mode-banner"><b>Loading</b> · Explore the screens. Loading your saved adventure. <button data-nav="profile">Connection details</button></div>`:''}<main id="main" tabindex="-1">${state.announcement?.enabled?`<aside class="callout"><b>${esc(state.announcement.title)}</b><p>${esc(state.announcement.body)}</p></aside>`:''}${!state.ready&&view==='profile'?`<section class="panel"><p class="eyebrow">OYO: UNLOCKED</p><h1>${state.connectionError?'Live connection required':'Connecting to your adventure…'}</h1><p>${esc(state.connectionError||'Loading your account connection.')}</p><p>This version requires the live Firebase services. No simulated progress or AI responses are available.</p></section>`:({map:mapView,unlocked:unlockedView,mission:missionView,guides:guidesView,boss:bossView,vault:vaultView,progress:progressView,resources:resourcesView,membership:membershipView,profile:profileView,review:reviewView,community:communityView,admin:adminView}[view]||mapView)()}</main>
 <footer class="game-footer"><span>${icon('ShieldCheck')} Progress is earned through proof.</span><span>${api.cloud?'Cloud mode':'Device adventure · self-reviewed proof'} · No income guarantees</span></footer></div>`;
 createIcons({icons,attrs:{'stroke-width':1.6}});bind();syncCommunity();if(!state.ready){document.querySelectorAll('form input,form textarea,form select,form button,[data-step]').forEach(el=>el.disabled=true);}}
function mapView(){const g=state.game,w=worlds[selectedWorld],open=worldOpen(g,w.index),done=missions.filter(m=>missionState(g,m.id).status==='verified').length;
 return title('OYO: UNLOCKED · THE UNWRITTEN REACH','Give the unknown a shape.',`<span class="season-tag">${icon('Star')} CHAPTER ${String(selectedWorld+1).padStart(2,'0')} · ${g.bosses[w.id]?.won?'CONQUERED':'EXPLORE'}</span>`)+`
 <section class="adventure-intro"><div><span class="eyebrow">REAL SKILLS. REAL ACTIONS.</span><h2>Build the life you want.<br><em>One unlock at a time.</em></h2><p>Enter a world. Meet your Guide. Take your next move into real life.</p></div><button class="primary" data-continue>Resume your adventure ${icon('ArrowRight')}</button></section><div class="map-layout"><section class="world-map" aria-label="Nine business worlds"><div class="map-caption"><span class="eyebrow">THE REAL-WORLD ADVENTURE</span><span>${done} / 18 missions verified</span></div><div class="map-art"><svg class="world-path" viewBox="0 0 900 600" preserveAspectRatio="none" aria-hidden="true"><path d="M150 110 H450 H750 Q860 210 750 300 H450 H150 Q40 410 150 500 H450 H750"/></svg><img src="${import.meta.env.BASE_URL}unwritten-reach.png" alt="Nine amethyst islands with golden constellation instruments in the Unwritten Reach" fetchpriority="high"><div class="map-worlds">${worlds.map(x=>`<button class="world-node ${selectedWorld===x.index?'selected':''} ${worldOpen(g,x.index)?'available':'locked'} ${g.bosses[x.id]?.won?'conquered':''}" data-world="${x.index}" aria-pressed="${selectedWorld===x.index}" aria-label="World ${x.index+1}, ${x.name}, ${worldOpen(g,x.index)?'available':'locked'}"><span class="world-sigil">${icon(g.bosses[x.id]?.won?'Check':worldOpen(g,x.index)?x.icon:'Lock')}</span><span class="world-label"><small>WORLD 0${x.index+1}</small><b>${x.name}</b></span></button>`).join('')}</div></div><div class="map-bottom"><span>${icon('Compass')} Select a world to explore</span><span>${icon('Lock')} Build. Prove. Unlock.</span></div></section>
 <aside class="quest-panel"><div class="quest-top"><span class="eyebrow">${open?'YOUR NEXT DESTINATION':'UNDISCOVERED WORLD'}</span><span class="world-number">0${w.index+1}</span></div><div class="large-sigil">${icon(w.icon)}</div><h2>${w.name}</h2><p class="muted">${w.tagline}.</p><div class="quest-rule"></div><p class="eyebrow">${open?'WORLD OBJECTIVES':'TO UNLOCK THIS WORLD'}</p>${open?missions.filter(m=>m.world===w.index).map(m=>`<button class="objective" data-mission="${m.id}" ${missionOpen(g,m.id)?'':'disabled'}><span class="objective-status">${icon(missionState(g,m.id).status==='verified'?'Check':missionOpen(g,m.id)?'ScrollText':'Lock')}</span><span><b>${m.title}</b><small>${missionState(g,m.id).status==='verified'?'Verified':missionState(g,m.id).status==='pending'?'Awaiting verification':missionOpen(g,m.id)?`${m.xp} XP · ready to play`:'Verify the previous mission'}</small></span></button>`).join(''):`<p>Verify both missions and defeat <b>${worlds[w.index-1].boss}</b> in ${worlds[w.index-1].name}.</p>`}
 <button class="boss-objective" data-nav="boss">${icon('Swords')}<span><small>WORLD BOSS</small><b>${w.boss}</b></span>${icon(g.bosses[w.id]?.won?'Check':bossReady(g,w.index)?'ArrowRight':'Lock')}</button>
 <button class="primary wide" data-continue ${!open?'disabled':''}>${g.bosses[w.id]?.won?'Revisit world':bossReady(g,w.index)?'Enter boss battle':'Continue adventure'} ${icon('ArrowRight')}</button><span class="quest-reward">${icon('Gem')} EARN THE ${w.name.toUpperCase()} CREST</span></aside></div>
 <section class="journey-strip" aria-label="Mission progression">${steps.map((s,i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><b>${s}</b>${i<6?icon('ChevronRight'):icon('KeyRound')}</div>`).join('')}</section>
 <section class="guide-preview"><div><p class="eyebrow">YOUR TEAM IS ALWAYS HERE</p><h2>Your Guides</h2><p>They grow as you do.</p></div><div class="guide-mini-row">${guides.map(x=>`<button class="guide-mini" data-guide="${x.id}">${portrait(guides.indexOf(x))}<b>${x.name}</b><small>LVL ${guideLevel(g,x.id)}</small><span class="talk-cta">TALK TO ME</span></button>`).join('')}</div></section>${bossPreview()}${worldEvolution()}`;
}
function missionView(){const g=state.game;let m=missions.find(x=>x.id===selectedMission)||missions[0];if(!missionOpen(g,m.id)){m=currentMission()||missions[0];selectedMission=m.id;}const s=missionState(g,m.id),w=worlds[m.world];
 let body='';if(s.step===0)body=`<span class="chapter-icon">${icon('BookOpen')}</span><h2>A small lesson. A real next step.</h2><p class="lesson">${m.lesson}</p><section class="training-module"><h3>${esc(training[m.world].title)}</h3>${training[m.world].teach.map(t=>`<p>${esc(t)}</p>`).join('')}<div class="callout"><b>Worked example</b><p>${esc(training[m.world].example)}</p></div><h3>Your workshop</h3><p>${esc(training[m.world].workshop)}</p><p><b>Quality check:</b> ${esc(training[m.world].check)}</p></section><div class="callout"><b>Your field mission</b><p>${m.irl}</p></div><button class="primary" data-step="0">Ready to practise ${icon('ArrowRight')}</button>`;
 if(s.step===1)body=`<h2>Put the idea to work.</h2><p class="lesson">${m.question}</p><form id="practice-form"><fieldset><legend>Choose one answer</legend>${m.answers.map((a,i)=>`<label class="answer"><input type="radio" name="answer" value="${i}" required><span>${a}</span></label>`).join('')}</fieldset><button class="primary">Check my answer ${icon('ArrowRight')}</button></form>`;
 if(s.step===2)body=`<h2>Build your first version.</h2><p>Use this framework and make it specific to your business.</p><form id="build-form"><label for="draft">Your business asset <small>60–6,000 characters</small></label><textarea id="draft" name="draft" minlength="60" maxlength="6000" required rows="10">${esc(sessionStorage.getItem('draft-'+(state.user?.uid||'signed-out')+'-'+m.id)||s.draft||m.template)}</textarea><button class="primary">Save asset & continue ${icon('ArrowRight')}</button></form>`;
 if(s.step===3)body=`<h2>Take it into the real world.</h2><p class="lesson">${m.irl}</p><details><summary>Your saved asset</summary><p class="prewrap">${esc(s.draft)}</p></details><div class="callout"><b>Keep it respectful.</b><p>Ask permission, remove private details, and report what really happened. Small results and thoughtful “no” decisions count.</p></div><form id="irl-form"><label class="answer"><input type="checkbox" name="confirmed" required><span>I completed the real action and have evidence to submit.</span></label><button class="primary">Prepare my proof ${icon('ArrowRight')}</button></form>`;
 if(s.step===4)body=`<h2>Show what you built.</h2>${s.feedback?`<p class="callout">Reviewer feedback: ${esc(s.feedback)}</p>`:''}<p>Explain the real action. Remove private customer details. Submit written evidence and, optionally, an HTTPS link.</p><form id="proof-form"><label for="summary">What did you do, and what happened?</label><textarea name="summary" id="summary" minlength="60" maxlength="6000" required rows="4" placeholder="Describe the action, context, and actual outcome. Minimum 60 characters."></textarea>${m.criteria.map((c,i)=>`<label for="evidence-${i}">${c}</label><textarea id="evidence-${i}" name="evidence-${i}" rows="2" minlength="20" maxlength="2000" required placeholder="Show how your evidence meets this criterion (20+ characters)."></textarea>`).join('')}<label for="proof-url">Evidence link <small>Optional · HTTPS</small></label><input id="proof-url" name="url" type="url" placeholder="https://"><button class="primary">Submit to Proof Vault ${icon('ShieldCheck')}</button></form>`;
 if(s.step===5)body=`<div class="outcome">${icon('ShieldCheck')}<p class="eyebrow">PROOF RECEIVED</p><h2>One step from your unlock.</h2><p>${api.cloud?'Your evidence is waiting for an authorised reviewer. You can explore Guides while you wait.':'Check every criterion against your actual work. Self-review unlocks your device adventure; it is not independent or owner verification.'}</p>${api.cloud?'<button class="primary" data-refresh>Check review status</button>':`<button class="primary" data-simulate="${s.proofId}">Confirm my evidence is complete ${icon('Check')}</button>`}<button class="secondary" data-nav="vault">View Proof Vault</button></div>`;
 if(s.step===6)body=`<div class="outcome success">${icon('Crown')}<p class="eyebrow">${api.cloud?'MISSION VERIFIED':'MISSION SELF-REVIEWED'}</p><h2>You earned your next step.</h2><div class="earned">+${m.xp} XP <span>+1 ${w.skill} skill</span></div><p>${esc(s.feedback)}</p><button class="primary" data-next>Continue adventure ${icon('ArrowRight')}</button><button class="secondary" data-nav="vault">View your proof</button></div>`;
 return title(`WORLD 0${w.index+1} / MISSION ${m.id.slice(1).padStart(2,'0')}`,m.title,`<span class="reward-pill">${icon('Zap')} ${m.xp} XP</span>`)+`<div class="mission-layout"><aside class="mission-rail">${steps.map((x,i)=>`<div class="step ${i===s.step?'current':''} ${i<s.step?'complete':''}"><span>${i<s.step?icon('Check'):i+1}</span><b>${x}</b></div>`).join('')}<p>Your next mission unlocks after proof is verified.</p><button class="secondary wide" data-nav="map">Return to world map</button></aside><section class="panel mission-content">${body}</section><aside class="mission-help"><div class="guide-orb">${icon(guides.find(x=>x.id===w.guide).icon)}</div><h3>${guides.find(x=>x.id===w.guide).name}</h3><p>LVL ${guideLevel(g,w.guide)} · YOUR GUIDE</p><p>Make it specific. A small, honest action beats a perfect plan.</p><button class="secondary wide" data-guide="${w.guide}">Ask your Guide</button><h3>Proof checklist</h3><ul>${m.criteria.map(c=>`<li>${c}</li>`).join('')}</ul></aside></div>`;
}
function guidesView(){const g=state.game,guide=guides.find(x=>x.id===selectedGuide);return title('YOUR PARTY','Six Guides. One shared adventure.')+`<div class="guide-picker">${guides.map(x=>`<button data-select-guide="${x.id}" class="guide-card ${x.id===guide.id?'selected':''}" aria-pressed="${x.id===guide.id}">${portrait(guides.indexOf(x))}<b>${x.name}</b><small>${x.role}</small><span class="gold">LEVEL ${guideLevel(g,x.id)}</span></button>`).join('')}</div><div class="two-col"><section class="panel"><p class="eyebrow">${guide.role.toUpperCase()}</p><h2>Talk with ${guide.name}</h2><div class="chat-log" aria-label="Conversation">${(g.chats[guide.id]||[]).map(c=>`<div class="chat ${c.role==='user'?'you':''}"><small>${c.role==='user'?'YOU':guide.name.toUpperCase()}</small><p class="prewrap">${esc(c.text)}</p></div>`).join('')||`<div class="chat"><p>Bring a draft, a question, or a place you feel stuck. Your Guide's capabilities grow with verified work.</p></div>`}</div><button class="secondary" data-save-conversation>Keep this conversation</button><form id="chat-form">${g.coaching?.[guide.id]?.question?`<div class="callout"><b>Next question</b><p>${esc(g.coaching[guide.id].question.text)}</p>${(g.coaching[guide.id].question.choices||[]).map(c=>`<button type="button" class="secondary" data-guide-answer="${esc(c)}">${esc(c)}</button>`).join('')}</div>`:''}<label for="message">Your answer or question</label><textarea name="message" id="message" minlength="3" maxlength="2000" required rows="3" placeholder="Help me think through my next action…"></textarea><button class="primary">Send to ${guide.name} ${icon('ArrowRight')}</button><button type="button" class="secondary" data-guide-reset>Start a fresh plan</button></form><p class="fine">${api.cloud?'Built-in coaching runs in your browser. Your answers and reviewed progress shape the questions; Firebase saves your conversations. No external AI provider is connected.':'Built-in strategy library.'}</p></section><aside class="panel"><div class="guide-full-portrait">${portrait(guides.indexOf(guide))}</div><h2>Guide level ${guideLevel(g,guide.id)}</h2><progress max="300" value="${(g.guideXp[guide.id]||0)%300}" aria-label="Guide level progress"></progress><p>${300-(g.guideXp[guide.id]||0)%300} Guide XP to next level</p><ul class="capabilities"><li>Level 1 · Explain & encourage</li><li>Level 3 · Compare & challenge</li><li>Level 6 · Diagnose & experiment</li></ul><p class="muted">Verify missions in this Guide's worlds to grow their capabilities. Chatting alone doesn't award XP.</p></aside></div>`;}
function bossView(){const g=state.game,w=worlds[selectedWorld],b=g.bosses[w.id]||{round:0,attempts:0},ready=bossReady(g,w.index),scenario=bossScenario(g,w);return title(`WORLD 0${w.index+1} / BOSS BATTLE`,w.boss,`<span class="reward-pill">${icon('Swords')} TIER ${w.index+1}</span>`)+`<section class="boss-stage"><div class="arena-floor" aria-hidden="true"></div><div class="boss-full-portrait">${portrait(w.index%5,1)}</div><p class="eyebrow">${b.won?'WORLD CONQUERED':ready?'THE CHALLENGE EVOLVES':'PROOF REQUIRED'}</p><h2>${b.won?'A new possibility is yours.':w.boss}</h2><div class="boss-health" aria-label="Boss rounds completed">${[0,1,2].map(i=>`<span class="${i<b.round?'hit':''}">${i<b.round?'COMPLETE':`ROUND ${i+1}`}</span>`).join('')}</div>${!ready?`<p>Verify both ${w.name} missions to unlock this battle.</p><button class="primary" data-nav="map">Return to your missions</button>`:b.won?`<p>${esc(optionNames[w.index])} unlocked. This is a prepared path to explore, not a promised financial result.</p><button class="primary" data-next-world>${w.index<8?'Explore the next world':'View your achievements'} ${icon('ArrowRight')}</button>`:`<p class="boss-prompt">${esc(scenario.prompt)}</p><form id="boss-form"><input type="hidden" name="scenarioId" value="${esc(scenario.id)}"><fieldset><legend>Choose your response strategy</legend>${scenario.options.map(o=>`<label class="answer"><input type="radio" name="choice" value="${o.id}" required><span>${esc(o.text)}</span></label>`).join('')}</fieldset><fieldset><legend>How will you check the outcome?</legend>${scenario.checks.map(o=>`<label class="answer"><input type="radio" name="check" value="${o.id}" required><span>${esc(o.text)}</span></label>`).join('')}</fieldset><p>${esc(scenario.reflection)}</p><label for="boss-answer">Your move <small>Respond to the objection, explain your next move, and how you will check fit</small></label><textarea id="boss-answer" name="answer" minlength="40" maxlength="3000" required rows="5" placeholder="What would you say to this person? What is your next step, and why?"></textarea><button class="primary">Make your move ${icon('Swords')}</button></form><p class="fine">${api.cloud?'Built-in strategy rubric: your two choices are assessed; your written reflection is saved for review, not automatically graded.':'Offline strategy challenge · evaluates your selected choice. Written reflections are saved, not AI-assessed.'} Difficulty increases each round.</p>`}${b.history?.length?`<details open><summary>Latest battle feedback · ${b.attempts} moves</summary><p>${esc(b.history.at(-1).feedback)}</p></details>`:''}</section>`;}
function vaultView(){const items=state.proofs.filter(p=>vaultFilter==='all'||p.status===vaultFilter);return title('REAL ACTIONS. A RECORD YOU KEEP.','The Proof Vault',`<button class="secondary" data-export>${icon('Download')} Export record</button>`)+`<div class="filter-row" aria-label="Filter proofs">${['all','pending','verified','rejected'].map(f=>`<button class="chip ${vaultFilter===f?'active':''}" data-filter="${f}" aria-pressed="${vaultFilter===f}">${f==='all'?'All proof':f}</button>`).join('')}</div><div class="vault-grid">${items.map(p=>`<article class="panel proof-card"><div class="proof-head"><span class="status ${p.status}">${icon(p.status==='verified'?'ShieldCheck':'ScrollText')}${p.status==='verified'&&!api.cloud?'self-reviewed':p.status}</span><small>${new Date(p.createdAt).toLocaleDateString()}</small></div><h2>${esc(missions.find(m=>m.id===p.missionId)?.title)}</h2><p>${esc(p.summary)}</p><details><summary>View criteria & review</summary>${(p.evidence||[]).map((e,i)=>`<p><b>${esc(missions.find(m=>m.id===p.missionId)?.criteria[i])}</b><br>${esc(e)}</p>`).join('')}<p>${esc(p.feedback||'Awaiting review.')}</p></details>${p.url?`<a class="text-link" href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Open submitted link ${icon('ExternalLink')}</a>`:''}${p.hasFile||p.attachment?`<button class="secondary" data-file="${p.id}">${icon('Download')} ${esc(p.fileName||p.attachment.name)}</button>`:''}${p.status==='pending'&&!api.cloud?`<button class="primary" data-simulate="${p.id}">Confirm my evidence is complete</button>`:''}</article>`).join('')||`<div class="empty-state">${icon('ShieldCheck')}<h2>Your actions belong here.</h2><p>${vaultFilter==='all'?'Complete your first mission and submit proof to start your collection.':'No proofs match this filter yet.'}</p><button class="primary" data-nav="mission">Open mission ${icon('ArrowRight')}</button></div>`}</div>`;}
function progressView(){const g=state.game;return title('YOUR CHARACTER IS EVOLVING','Look at what you’ve built.')+`<div class="stats-grid"><div class="panel"><span>TOTAL EXPERIENCE</span><strong>${g.xp}</strong><small>Level ${level(g)}</small></div><div class="panel"><span>COMPLETED MISSIONS</span><strong>${Object.values(g.missions).filter(x=>x.status==='verified').length}<small> / 18</small></strong><small>${api.cloud?'Reviewed evidence':'Self-reviewed on this device'}</small></div><div class="panel"><span>WORLDS CONQUERED</span><strong>${Object.values(g.bosses).filter(x=>x.won).length}<small> / 9</small></strong><small>Every world opens a possibility</small></div></div><div class="two-col"><section class="panel"><h2>Your skill tree</h2>${['Strategy','Creativity','Building','Connection','Analysis','Momentum'].map(s=>`<div class="skill-line"><span>${s}</span><progress max="6" value="${g.skills[s]||0}" aria-label="${s} skill points"></progress><b>${g.skills[s]||0}</b></div>`).join('')}<h2 class="mt">Achievement collection</h2><div class="badges">${g.achievements.map(a=>`<span>${icon('Crown')}${esc(a)}</span>`).join('')||'<p class="muted">Your first crest is waiting beyond your first proof.</p>'}</div></section><section class="panel"><h2>Your options</h2><p>Prepared paths you can explore. These are game unlocks, not verified income sources.</p>${optionNames.map(o=>`<div class="option-line ${g.options.includes(o)?'earned-option':''}">${icon(g.options.includes(o)?'KeyRound':'Lock')}<span>${o}</span></div>`).join('')}</section></div>`;}
function resourcesView(){clearBankURLs();const images=bankItems.filter(x=>x.kind==='screenshot').length,notes=bankItems.length-images;const shown=bankItems.filter(x=>bankFilter==='all'||x.kind===bankFilter);return title('YOUR INVENTORY','The Proof Bank',`<button class="secondary" data-bank-refresh>Open / refresh my bank</button>`)+`<section class="panel bank-offload"><h2>Move your inventory to your phone</h2><p>Download one ZIP containing all your screenshots, captions, templates and conversations. Open it in Files or Downloads and check your items, then confirm below to free their game storage.</p><button class="primary" data-bank-export>1 · Download my Proof Bank</button>${bankExport?`<button class="secondary" data-bank-empty>2 · I saved the ZIP — free my game storage</button><p class="fine">Only the ${bankExport.length} unchanged items in this download will be removed. Mission progress, XP and submitted evidence stay in your account.</p>`:''}</section><section class="panel bank-intro mt"><h2>Keep the traces of your adventure.</h2><p>Screenshots, useful words, templates and conversations belong here. Items are private to your account and saved across devices. Saving an item does not award XP or submit it for review.</p><div class="button-row"><span class="reward-pill">${bankLoaded?images:'—'} / 12 screenshot slots</span><span class="reward-pill">${bankLoaded?notes:'—'} / 24 journal slots</span><button class="secondary" data-nav="vault">View submitted mission evidence</button></div><p class="fine">Screenshots are resized to fit 180 KB each. Keep your original if small text matters. Journal items hold up to 12,000 characters. The game also has a shared storage allowance. When it is full, save to your phone/device instead. Download or remove items to make room.</p></section>${state.user?`<div class="two-col mt"><section class="panel"><h2>Store a screenshot</h2><form id="bank-image-form"><label for="bank-image-title">Item name</label><input id="bank-image-title" name="title" maxlength="80" required><label for="bank-file">Screenshot</label><input id="bank-file" name="file" type="file" accept="image/png,image/jpeg,image/webp" required><label for="bank-caption">What does it show?</label><textarea id="bank-caption" name="text" maxlength="12000" rows="2"></textarea><button class="primary">Add to inventory</button><button type="button" class="secondary" data-bank-local-image>Save original to phone/device</button></form></section><section class="panel"><h2>Keep useful words</h2><form id="bank-note-form"><label for="bank-note-title">Item name</label><input id="bank-note-title" name="title" maxlength="80" required><label for="bank-kind">Item type</label><select id="bank-kind" name="kind"><option value="note">Field note</option><option value="template">Template</option><option value="conversation">Conversation</option></select><label for="bank-text">What do you want to keep?</label><textarea id="bank-text" name="text" maxlength="12000" rows="6" required></textarea><button class="primary">Store in journal</button><button type="button" class="secondary" data-bank-local-note>Save to phone/device</button></form></section></div>`:'<section class="panel mt"><p>Sign in to open your private inventory.</p><button class="primary" data-nav="profile">Create account or sign in</button></section>'}<div class="filter-row mt">${['all','screenshot','template','conversation','note'].map(k=>`<button class="chip ${bankFilter===k?'active':''}" data-bank-filter="${k}">${k==='all'?'All items':k}</button>`).join('')}</div><div class="bank-grid">${shown.map(item=>`<article class="panel bank-item"><span class="eyebrow">${esc(item.kind)} · SAVED ITEM</span>${item.kind==='screenshot'?`<img class="bank-screenshot" src="${bankImage(item)}" alt="${esc(item.title)}">`:icon(item.kind==='conversation'?'MessagesSquare':'ScrollText')}<h2>${esc(item.title)}</h2><details><summary>Inspect item</summary><p class="prewrap">${esc(item.text||'No caption added.')}</p></details><div class="button-row"><button class="secondary" data-bank-download="${esc(item.id)}">Download</button><button class="text-button" data-bank-delete="${esc(item.id)}">Remove</button></div></article>`).join('')||`<section class="panel"><p>${bankLoaded?'No items in this collection yet. Save your first discovery above.':'Open your bank to load saved items.'}</p></section>`}</div><section class="panel mt"><h2>Starter template · The Seed Ledger</h2><p>Mark the unknown → make a small move → bring back a trace → reweave the path.</p><button class="secondary" data-bank-template>Keep this template</button><button class="secondary" data-kit>Download template</button></section>`;}
function membershipView(){const tester=activeTester(state.tester),paid=activeMembership(state.membership);return title('PAYPAL SUBSCRIPTIONS','Your adventure pass')+`<section class="panel membership"><h2>${tester?'Your tester pass is active':paid?'Your pass is active.':state.membershipRequired?'Start free. Unlock more when you’re ready.':'The adventure is currently open.'}</h2>${tester?`<p>No subscription is needed while your tester access lasts. ${state.tester.expiresAt?'Tester access ends '+new Date(state.tester.expiresAt).toLocaleString(): 'It lasts until the owner removes it.'}</p>`:''}${paid?`<p>Access through <strong>${new Date(state.membership.expiresAt).toLocaleString()}</strong>.</p>`:''}<p>World one is free. Later worlds open as you complete their missions and bosses.</p>${state.checkoutReady?`<p>Subscribe through PayPal. Verified payments activate and renew your game access automatically. Payment confirmation can take a moment; use Refresh my access after returning.</p>${!tester&&!paid?`<button class="primary" data-checkout>${esc(state.billing?.offerLabel||'Subscribe through PayPal')}</button>`:''}`:'<p class="callout">Automatic subscriptions are not connected yet. Checkout is unavailable until the owner completes setup.</p>'}${state.automaticMembership?.status==='PAYMENT_REVIEW'?'<p class="callout">A refunded or reversed payment needs owner review before subscription access can resume.</p>':''}<a class="secondary" href="https://www.paypal.com/myaccount/autopay/" target="_blank" rel="noopener noreferrer">Manage PayPal subscription ↗</a><p class="fine">Cancelling stops future renewals. Confirmed paid access lasts through its recorded date. Tester access does not cancel a separate PayPal subscription.</p>${state.user?`<p>Your Player ID: <code>${esc(state.user.uid)}</code>. Share this with the owner for tester access.</p><button class="secondary" data-refresh>Refresh my access</button>`:'<button class="primary" data-nav="profile">Create account or sign in</button>'}</section>`;}

function profileView(){const p=state.game.profile;return title('YOUR CHARACTER','Make this adventure yours.')+`<div class="two-col"><section class="panel"><form id="profile-form"><div class="large-sigil">${icon(p.avatar)}</div><label for="name">Player name</label><input name="name" id="name" value="${esc(p.name)}" maxlength="32" required><fieldset><legend>Choose your sigil</legend><div class="avatar-picker">${['Compass','Feather','Gem','Flame','Shield','Crown'].map(a=>`<label class="avatar-choice"><input type="radio" name="avatar" value="${a}" ${p.avatar===a?'checked':''}><span>${icon(a)}<small>${a}</small></span></label>`).join('')}</div></fieldset><label for="path">Your starting path</label><select name="path" id="path">${['Creator','Affiliate','Service','Digital products','Coach','Local business'].map(x=>`<option ${p.path===x?'selected':''}>${x==='Affiliate'?'Community projects':x}</option>`).join('')}</select><label for="business">Your business or idea</label><textarea name="business" id="business" maxlength="500" rows="3">${esc(p.business)}</textarea><button class="primary">Save character ${icon('Check')}</button></form></section><section class="panel"><h2>${api.cloud?'Your account':'Saved on this device'}</h2><p>Your account and progress are saved with Firebase. Sign in on another device to continue. Account setup, password recovery, community chat, and saving Guide conversations require internet.</p>${state.connectionError?`<p role="status">${esc(state.connectionError)}</p>`:''}${api.cloud?(state.user?`<p>Signed in as ${esc(state.user.email)}</p><button class="secondary" data-refresh>Reload saved adventure</button><button class="secondary" data-signout>${icon('LogOut')} Sign out</button>`:`<form id="auth-form"><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="email" required><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" minlength="8" required><div class="button-row"><button class="primary" name="kind" value="signin">Sign in</button><button class="secondary" name="kind" value="signup">Create account</button></div></form>`):'<p>Your adventure saves in this browser without a password. Export a backup to protect against device loss or cleared browser data. An online account has a separate, owner-reviewed adventure.</p>'}${api.cloud?`<details><summary>Forgot your password?</summary><p>Enter your account email. Use the secure link in the email to choose a new password. We cannot display your old password. Check spam if the message does not arrive.</p><form id="reset-form"><label for="reset-email">Account email</label><input id="reset-email" name="email" type="email" autocomplete="email" required><button class="secondary">Send password-reset link</button></form></details>`:`<label for="restore-file">Restore a device backup</label><input id="restore-file" type="file" accept="application/json,.json"><p class="fine">Export includes your progress and evidence text. Download evidence attachments separately; they are not in the backup. Restoring replaces this device save.</p>`}<h2 class="mt">Game settings</h2><label class="answer"><input id="sound-pref" type="checkbox" ${prefs.sound?'checked':''}><span>Play unlock sounds</span></label><label class="answer"><input id="motion-pref" type="checkbox" ${prefs.motion?'checked':''}><span>Reduce motion</span></label><div class="button-row"><button class="secondary" data-install>${icon('Download')} Install app</button><button class="secondary" data-export>Export progress</button></div><p class="fine">On iPhone or iPad, use Safari → Share → Add to Home Screen. On supported desktop browsers, use the install icon in the address bar.</p>${!api.cloud?'<details><summary>Reset device adventure</summary><p>This removes this browser’s device progress and uploaded evidence files.</p><button class="danger" data-reset>Reset this device’s device save</button></details>':''}</section></div>`;}
function adminView(){if(!state.isOwner)return '<section class="panel"><h1>Owner access only</h1><p>This area is not available to this account.</p></section>';const a=adminOverview?.announcement||state.announcement||{title:'',body:'',enabled:false};return title('PRIVATE · YOUR ACCOUNT ONLY','Owner Admin',`<button class="secondary" data-admin-refresh>Refresh overview</button>`)+`<div class="stats-grid"><section class="panel"><span>PLAYERS</span><strong>${adminOverview?.playerCount??'—'}</strong></section><section class="panel"><span>PROOFS WAITING</span><strong>${adminOverview?.pendingProofs??'—'}</strong></section></div><div class="two-col"><section class="panel"><h2>Manage your game</h2><div class="admin-links"><button class="secondary" data-nav="resources">Open Proof Bank ${icon('ExternalLink')}</button><button class="secondary" data-admin-proofs>Review player proof ${icon('ShieldCheck')}</button></div><p class="fine">Only your registered owner account can use these controls. Players cannot grant themselves admin access.</p><button class="secondary" data-nav="community">Manage community chat</button><h3>Game content and paid offers</h3><p>Lessons, worlds, and Guide instructions remain in the source code. Those changes require an updated deployment; this editor does not grant arbitrary code execution or change player XP. PayPal connection settings are below.</p></section><section class="panel"><h2>Player announcement</h2><p>Add or update a message for your players. This announcement becomes visible to signed-in players after they refresh.</p><form id="announcement-form"><label for="announcement-title">Title</label><input id="announcement-title" name="title" maxlength="100" value="${esc(a.title)}"><label for="announcement-body">Message</label><textarea id="announcement-body" name="body" maxlength="1500" rows="6">${esc(a.body)}</textarea><label class="answer"><input type="checkbox" name="enabled" ${a.enabled?'checked':''}>Show this announcement to players</label><button class="primary">Save announcement</button></form></section></div>${testerAdmin()}${membershipAdmin()}`;}
function reviewView(){return title('AUTHORISED REVIEWERS','Proof review queue',`<button class="secondary" data-load-queue>Refresh queue</button>`)+(!state.reviewer?'<p>This area requires a reviewer account.</p>':`<div class="vault-grid">${queue.map(p=>`<article class="panel"><h2>${esc(missions.find(m=>m.id===p.missionId)?.title)}</h2><p>${esc(p.summary)}</p>${p.evidence.map((x,i)=>`<p><b>${esc(missions.find(m=>m.id===p.missionId).criteria[i])}</b><br>${esc(x)}</p>`).join('')}${p.url?`<a href="${esc(p.url)}" target="_blank" rel="noopener noreferrer">Open submitted link</a>`:''}${p.attachment?`<button class="secondary" data-review-file="${p.id}">Download submitted file</button>`:''}<form class="review-form" data-proof="${p.id}" data-uid="${esc(p.uid)}"><label for="feedback-${p.id}">Review feedback</label><textarea name="feedback" id="feedback-${p.id}" minlength="10" maxlength="2000" required></textarea><button class="primary" name="decision" value="approve">Approve proof</button><button class="secondary" name="decision" value="reject">Request revision</button></form></article>`).join('')||'<p>Refresh to load pending proofs. You cannot review your own submissions.</p>'}</div>`);}
function download(blob,name){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function bind(){
 $('[data-bank-export]')?.addEventListener('click',()=>run(async()=>{const items=await api.loadBank(),zip=exportBank(items);download(zip,'oyo-proof-bank-'+new Date().toISOString().slice(0,10)+'.zip');bankExport=items.map(x=>({id:x.id,savedAt:x.savedAt?.toMillis?.()??x.savedAt}));bankItems=items;bankLoaded=true;render();notify('Open the ZIP on your device and check your items before freeing game storage.');}));
 $('[data-bank-empty]')?.addEventListener('click',()=>{if(!bankExport||!confirm('Have you opened the downloaded ZIP and checked your items? Remove those backed-up items from the game now?'))return;run(async()=>{const backup=bankExport;let removed=0;try{for(const item of backup){await api.deleteBankItem(item.id,item.savedAt);removed++;}bankExport=null;notify('Backed-up items removed and game storage freed. Your mission progress and XP are unchanged.');}catch(e){throw Error(removed+' items cleared. '+e.message+' Your downloaded backup is unchanged.');}finally{await reloadBank();}});});

 $('[data-bank-local-image]')?.addEventListener('click',()=>{const file=$('#bank-file')?.files?.[0];if(!file)return notify('Choose a screenshot first.',true);download(file,file.name);notify('Download requested. Check your device’s Files or Downloads folder.');});
 $('[data-bank-local-note]')?.addEventListener('click',()=>{const f=new FormData($('#bank-note-form'));download(new Blob([String(f.get('title')||'Field note')+'\n\n'+String(f.get('text')||'')],{type:'text/plain'}),'oyo-field-note.txt');notify('Download requested. Check your device’s Files or Downloads folder.');});
 $('[data-bank-refresh]')?.addEventListener('click',()=>run(reloadBank));
 document.querySelectorAll('[data-bank-filter]').forEach(b=>b.onclick=()=>{bankFilter=b.dataset.bankFilter;render();});
 $('#bank-image-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.target,f=new FormData(form);run(async()=>{const image=await compressScreenshot(f.get('file'));await api.saveBankItem({kind:'screenshot',title:f.get('title'),text:f.get('text'),...image});form.reset();await reloadBank();notify('Screenshot stored in your Proof Bank.');});});
 $('#bank-note-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.target,fields=Object.fromEntries(new FormData(form));run(async()=>{await api.saveBankItem(fields);form.reset();await reloadBank();notify('Journal item saved.');});});
 $('[data-save-conversation]')?.addEventListener('click',()=>run(async()=>{await api.saveBankItem(conversationItem(guides.find(g=>g.id===selectedGuide),state.game.chats[selectedGuide]));bankLoaded=false;notify('Conversation kept in your Proof Bank.');}));
 $('[data-bank-template]')?.addEventListener('click',()=>run(async()=>{await api.saveBankItem({kind:'template',title:'The Seed Ledger',text:'MARK THE UNKNOWN\nMy question / what would change my mind\n\nMAKE A SMALL MOVE\nAction / time limit / permission / stopping point\n\nBRING BACK A TRACE\nActual observation / evidence / uncertainty\n\nREWEAVE THE PATH\nKeep / change / leave behind / next experiment'});await reloadBank();notify('Template added to your journal.');}));
 document.querySelectorAll('[data-bank-download]').forEach(b=>b.onclick=()=>{const item=bankItems.find(x=>x.id===b.dataset.bankDownload);if(item)download(new Blob([item.kind==='screenshot'?item.image:item.title+'\n\n'+item.text],{type:item.kind==='screenshot'?'image/jpeg':'text/plain'}),'oyo-'+item.id+(item.kind==='screenshot'?'.jpg':'.txt'));});
 document.querySelectorAll('[data-bank-delete]').forEach(b=>b.onclick=()=>{if(confirm('Remove this saved item from your Proof Bank? Download it first if you want a copy.'))run(async()=>{await api.deleteBankItem(b.dataset.bankDelete);await reloadBank();notify('Inventory item removed. Your mission progress is unchanged.');});});

 $('#membership-request-form')?.addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));run(async()=>{await api.requestMembership(d);notify('Request saved. The owner must confirm your payment in PayPal.');});});
 $('#billing-settings-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);run(async()=>{await api.saveBilling({apiUrl:f.get('apiUrl'),offerLabel:f.get('offerLabel'),requireMembership:f.get('requireMembership')==='on'});notify('Payment server and membership setting saved.');});});
 document.querySelectorAll('[data-review-member]').forEach(b=>b.onclick=()=>{const r=adminOverview?.membershipRequests?.find(r=>r.id===b.dataset.reviewMember);if(r){$('#member-uid').value=r.id;$('#member-reference').value=r.reference;$('#member-uid').scrollIntoView({block:'center'});}});
 $('#tester-access-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),active=e.submitter?.value==='grant';run(async()=>{await api.saveTester({uid:f.get('uid').trim(),active,expiresAt:active&&f.get('expiresAt')?new Date(f.get('expiresAt')).getTime():0,note:f.get('note')});adminOverview=await api.getAdminOverview();render();notify(active?'Tester access granted. No payment needed.':'Tester access removed. Any separate paid pass remains unchanged.');});});
 document.querySelectorAll('[data-edit-tester]').forEach(b=>b.onclick=()=>{const t=adminOverview?.testers?.find(t=>t.id===b.dataset.editTester);if(!t)return;$('#tester-uid').value=t.id;$('#tester-note').value=t.note||'';const d=new Date(t.expiresAt);$('#tester-expiry').value=t.expiresAt?new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16):'';$('#tester-uid').scrollIntoView({block:'center'});});
 $('#member-access-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),active=e.submitter?.value==='grant';run(async()=>{await api.saveMembership({uid:f.get('uid'),active,expiresAt:active?new Date(f.get('expiresAt')).getTime():0,reference:f.get('reference'),note:f.get('note'),confirmed:f.get('confirmed')==='on'});adminOverview=await api.getAdminOverview();render();notify(active?'Paid access saved through the verified date.':'Access revoked.');});});

 document.querySelectorAll('[data-boss-world]').forEach(b=>b.onclick=()=>{selectedWorld=Number(b.dataset.bossWorld);go('boss');});
 document.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>run(async()=>{await api.action({type:'equip',rewardId:b.dataset.equip});sound();notify('Reward equipped. Your character has evolved.');}));
 document.querySelectorAll('[data-guide-answer]').forEach(b=>b.onclick=()=>run(()=>api.chat(selectedGuide,b.dataset.guideAnswer)));
 $('[data-guide-reset]')?.addEventListener('click',()=>{if(confirm('Start fresh questions for this Guide? Your missions and XP remain unchanged.'))run(()=>api.chat(selectedGuide,'Start a fresh plan',true));});

 $('#community-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.target,text=new FormData(form).get('text'),id=form.dataset.id||crypto.randomUUID();form.dataset.id=id;run(async()=>{await api.sendChat(text,id);form.reset();delete form.dataset.id;});});
 $('#community-text')?.addEventListener('input',()=>{delete $('#community-form').dataset.id;});
 $('[data-community-reports]')?.addEventListener('click',()=>run(async()=>{communityReports=await api.getChatReports();paintCommunity();}));

 document.querySelectorAll('[data-admin-refresh]').forEach(b=>b.addEventListener('click',()=>run(async()=>{adminOverview=await api.getAdminOverview();render();}))); 
 $('[data-admin-proofs]')?.addEventListener('click',()=>run(async()=>{queue=await api.reviewQueue();go('review');}));
 $('#announcement-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);run(async()=>{await api.saveAnnouncement({title:f.get('title'),body:f.get('body'),enabled:f.get('enabled')==='on'});adminOverview=await api.getAdminOverview();render();notify('Announcement saved.');});});

document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));document.querySelectorAll('[data-world]').forEach(b=>b.onclick=()=>{selectedWorld=Number(b.dataset.world);render();});document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{selectedMission=b.dataset.mission;go('mission');});document.querySelectorAll('[data-guide]').forEach(b=>b.onclick=()=>{selectedGuide=b.dataset.guide;go('guides');});document.querySelectorAll('[data-select-guide]').forEach(b=>b.onclick=()=>{selectedGuide=b.dataset.selectGuide;render();});
 document.querySelectorAll('[data-continue]').forEach(button=>button.addEventListener('click',()=>{const m=missions.find(x=>x.world===selectedWorld&&missionState(state.game,x.id).status!=='verified');if(m){selectedMission=m.id;go('mission')}else go('boss');}));
 $('[data-step]')?.addEventListener('click',()=>run(()=>api.action({type:'step',missionId:selectedMission,expectedStep:0})));
 $('#practice-form')?.addEventListener('submit',e=>{e.preventDefault();run(()=>api.action({type:'step',missionId:selectedMission,expectedStep:1,answer:Number(new FormData(e.target).get('answer'))}));});
 $('#draft')?.addEventListener('input',e=>sessionStorage.setItem('draft-'+(state.user?.uid||'signed-out')+'-'+selectedMission,e.target.value));
 $('#build-form')?.addEventListener('submit',e=>{e.preventDefault();const draft=new FormData(e.target).get('draft');run(async()=>{await api.action({type:'step',missionId:selectedMission,expectedStep:2,draft});sessionStorage.removeItem('draft-'+(state.user?.uid||'signed-out')+'-'+selectedMission);});});
 $('#irl-form')?.addEventListener('submit',e=>{e.preventDefault();run(()=>api.action({type:'step',missionId:selectedMission,expectedStep:3,confirmed:true}));});
 $('#proof-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);run(async()=>{await api.submitProof(selectedMission,{summary:f.get('summary'),evidence:[0,1,2].map(i=>f.get('evidence-'+i)),url:f.get('url')});notify('Your written proof is saved in the vault.');});});
 document.querySelectorAll('[data-simulate]').forEach(b=>b.onclick=()=>run(async()=>{if(!confirm('I have completed the real-world action and checked every evidence criterion. This records my own review, not owner verification.'))return;await api.simulateReview(b.dataset.simulate);sound();notify('Self-review recorded. Your next device step is unlocked.');}));
 $('[data-next]')?.addEventListener('click',()=>{const m=missions.find(x=>x.id===selectedMission);selectedWorld=m.world;const next=missions.find(x=>x.world===m.world&&missionState(state.game,x.id).status!=='verified');if(next){selectedMission=next.id;render()}else go('boss');});
 $('[data-next-world]')?.addEventListener('click',()=>{if(selectedWorld<8){selectedWorld++;go('map')}else go('progress');});
 $('#chat-form')?.addEventListener('submit',e=>{e.preventDefault();const message=new FormData(e.target).get('message');run(async()=>{await api.chat(selectedGuide,message);$('#message').value='';$('.chat-log').scrollTop=99999;});});
 $('#boss-form')?.addEventListener('submit',e=>{e.preventDefault();const answer=new FormData(e.target).get('answer');run(async()=>{const r=await api.fight(worlds[selectedWorld].id,answer,new FormData(e.target).get('choice'),new FormData(e.target).get('check'),new FormData(e.target).get('scenarioId'));if(r.passed)sound();notify(r.feedback,!r.passed);});});
 document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{vaultFilter=b.dataset.filter;render()});document.querySelectorAll('[data-file]').forEach(b=>b.onclick=()=>run(async()=>{const p=state.proofs.find(x=>x.id===b.dataset.file);download(await api.proofFile(p),p.fileName||p.attachment.name);}));
 document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>download(api.exportSave(),'oyo-progress.json'));
 $('[data-kit]')?.addEventListener('click',()=>download(new Blob(['OYO: UNLOCKED — THE SEED LEDGER\n\nMARK THE UNKNOWN\nMy question / who or what can teach me / what would change my mind\n\nMAKE A SMALL MOVE\nAction / time limit / permission / stopping point\n\nBRING BACK A TRACE\nActual observation / evidence / what remains uncertain\n\nREWEAVE THE PATH\nKeep / change / leave behind / next experiment\n\nRespect consent. Remove personal details from shared evidence.'],{type:'text/plain'}),'oyo-seed-ledger.txt'));
 $('[data-checkout]')?.addEventListener('click',()=>run(()=>api.checkout()));
 $('#profile-form')?.addEventListener('submit',e=>{e.preventDefault();const profile=Object.fromEntries(new FormData(e.target));run(async()=>{await api.action({type:'profile',profile});notify('Character saved.');});});
 $('#auth-form')?.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),kind=e.submitter.value;run(async()=>{await api.auth(kind,f.get('email'),f.get('password'));notify(kind==='reset'?'If the address has an account, a reset email will arrive.':'Welcome to your adventure.');});});
 document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>api.switchMode(b.dataset.mode));
 $('#reset-form')?.addEventListener('submit',e=>{e.preventDefault();run(async()=>{await api.auth('reset',new FormData(e.target).get('email'),'');notify('If this address has an account, a password-reset email will arrive.');});});
 $('#restore-file')?.addEventListener('change',e=>{const f=e.target.files[0];if(f&&confirm('Replace the current device adventure with this backup?'))run(()=>api.importSave(f));});
 $('[data-signout]')?.addEventListener('click',()=>run(()=>api.signOut()));
 ['sound','motion'].forEach(k=>$('#'+k+'-pref')?.addEventListener('change',e=>{prefs[k]=e.target.checked;localStorage.setItem('oyo-preferences',JSON.stringify(prefs));render();}));
 $('[data-install]')?.addEventListener('click',()=>run(async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;}else notify('Use your browser’s Install app or Add to Home Screen option. Installation requires HTTPS or localhost.');}));
 $('[data-reset]')?.addEventListener('click',()=>{if(confirm('Delete this browser’s device progress and proof files? This cannot be undone.'))run(()=>api.resetLocal());});
 $('[data-refresh]')?.addEventListener('click',()=>run(()=>api.refreshPlayer()));
 $('[data-load-queue]')?.addEventListener('click',()=>run(async()=>{queue=await api.reviewQueue();render();}));
 document.querySelectorAll('[data-review-file]').forEach(b=>b.onclick=()=>run(async()=>{const p=queue.find(x=>x.id===b.dataset.reviewFile);download(await api.proofFile(p),p.attachment.name);}));
 document.querySelectorAll('.review-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();const data={uid:f.dataset.uid,proofId:f.dataset.proof,approved:e.submitter.value==='approve',feedback:new FormData(f).get('feedback')};run(async()=>{await api.reviewProof(data);queue=await api.reviewQueue();render();notify('Review saved.');});});
}
render();window.oyoBoot?.ready();api.initBackend(s=>{if(state.user?.uid!==s.user?.uid){adminOverview=null;queue=[];bankItems=[];bankLoaded=false;bankExport=null;clearBankURLs();hydrated=false;}state=s;if(!hydrated){selectedWorld=worlds.find(w=>worldOpen(s.game,w.index)&&!s.game.bosses[w.id]?.won)?.index??8;selectedMission=currentMission()?.id||missions[selectedWorld*2].id;hydrated=true;}render();}).catch(e=>notify(e.message,true));
if('serviceWorker' in navigator&&import.meta.env.PROD)window.addEventListener('load',()=>navigator.serviceWorker.register(import.meta.env.BASE_URL+'sw.js').catch(()=>notify('Offline shell could not be installed. The online game still works.',true)));

function communityView(){return title('YOUR COMMUNITY','The player lounge')+`<section class="panel"><p>Share wins, ask questions, and support other players. Messages and player names are visible to signed-in players. Keep customer details and private information out of this room.</p>${!state.user?'<button class="primary" data-nav="profile">Sign in to join</button>':`<p id="community-status" role="status">${navigator.onLine?'Connecting to community…':'Reconnect to use community chat.'}</p><div id="community-log" class="chat-log" aria-label="Community messages"></div><form id="community-form"><label for="community-text">Message</label><textarea id="community-text" name="text" minlength="1" maxlength="800" required></textarea><button class="primary">Send message</button></form>${state.isOwner?'<button class="secondary" data-community-reports>Load reported messages</button><div id="community-reports"></div>':''}`}</section>`;}
function syncCommunity(){const uid=view==='community'&&navigator.onLine?state.user?.uid:null;if(uid!==communityUid){communityStop?.();communityStop=null;communityUid=uid;communityMessages=[];communityReports=[];if(uid){try{communityStop=api.watchGamerChat(messages=>{communityMessages=messages;paintCommunity();},e=>{if($('#community-status'))$('#community-status').textContent=e.message;});}catch(e){notify(e.message,true);}}}paintCommunity();}
function paintCommunity(){const log=$('#community-log');if(!log)return;log.innerHTML=communityMessages.map(m=>`<article class="chat"><b>${esc(m.playerName)}</b><p class="prewrap">${esc(m.text)}</p>${!m.removed?`<button class="text-button" data-community-report="${esc(m.id)}">Report</button>${state.isOwner?`<button class="text-button" data-community-remove="${esc(m.id)}">Remove</button><button class="text-button" data-community-mute="${esc(m.id)}">Remove & mute 24 hours</button>`:''}`:''}</article>`).join('')||'<p>No messages yet.</p>';if($('#community-status'))$('#community-status').textContent=navigator.onLine?'Live community':'Reconnect to use community chat.';
 document.querySelectorAll('[data-community-report]').forEach(b=>b.onclick=()=>{const reason=prompt('Why are you reporting this message?');if(reason)run(async()=>{await api.reportChat(b.dataset.communityReport,reason);notify('Report sent to the owner.');});});
 for(const action of ['remove','mute'])document.querySelectorAll('[data-community-'+action+']').forEach(b=>b.onclick=()=>run(()=>api.moderateChat(b.dataset[action==='remove'?'communityRemove':'communityMute'],action==='mute')));
 const reports=$('#community-reports');if(reports){reports.innerHTML=communityReports.map(r=>`<article class="chat"><p>${esc(r.messageText)}</p><p>Report: ${esc(r.reason)}</p><button data-resolve-community="${esc(r.id)}">Resolve report</button></article>`).join('');document.querySelectorAll('[data-resolve-community]').forEach(b=>b.onclick=()=>run(async()=>{await api.resolveChatReport(b.dataset.resolveCommunity);communityReports=await api.getChatReports();paintCommunity();}));}}

function unlockedView(){const g=state.game,earned=rewardCatalogue.filter(r=>rewardEarned(g,r));return title('THE REWARD ROOM','UNLOCKED',`<span class="reward-pill">${icon('Gem')} ${earned.length} / ${rewardCatalogue.length} EARNED</span>`)+`<section class="reward-hero"><div class="reward-emblem">${icon('Crown')}</div><div><p class="eyebrow">YOUR REAL-WORLD ACTIONS CHANGE YOUR WORLD</p><h2>${esc(g.cosmetics?.title||'Every legend starts somewhere.')}</h2><p>Collect crests, unlock character titles, and equip new auras. Rewards are earned through reviewed proof and boss victories.</p></div><button class="primary" data-nav="mission">Find my next quest ${icon('ArrowRight')}</button></section><div class="reward-grid">${rewardCatalogue.map(r=>{const earned=rewardEarned(g,r),equipped=g.cosmetics?.[r.slot]===r.value;return `<article class="reward-card ${earned?'earned':'sealed'}"><div class="reward-art ${r.id}">${icon(earned?r.icon:'Lock')}</div><p class="eyebrow">${r.slot==='title'?'CHARACTER TITLE':'WORLD AURA'}</p><h2>${esc(r.name)}</h2><p>${esc(r.description)}</p><small>${earned?'EARNED':esc(r.requirement)}</small><button class="${earned?'primary':'secondary'} wide" data-equip="${r.id}" ${!earned||equipped?'disabled':''}>${equipped?'Equipped':earned?'Equip reward':'Locked'}</button></article>`}).join('')}</div><section class="panel crest-collection"><p class="eyebrow">WORLD TROPHIES</p><h2>Your crest collection</h2><div class="crest-row">${worlds.map(w=>`<button data-world-reward="${w.index}" class="crest ${g.bosses[w.id]?.won?'earned':'sealed'}" aria-label="${esc(w.name)} crest, ${g.bosses[w.id]?.won?'earned':'locked'}" disabled>${icon(g.bosses[w.id]?.won?w.icon:'Lock')}<span>${w.name}</span></button>`).join('')}</div></section>`;}

function bossPreview(){return `<section class="boss-preview"><div class="section-caption"><p class="eyebrow">FACE THE CHALLENGES. BUILD THE SKILLS.</p><h2>Real-world boss battles</h2></div><div class="boss-card-row">${worlds.map((w,i)=>`<button class="boss-card" data-boss-world="${i}">${portrait(i%5,1)}<strong>${esc(w.boss)}</strong><small>${esc(w.name)} · Tier ${i+1}</small><span class="talk-cta">${state.game.bosses[w.id]?.won?'CONQUERED':bossReady(state.game,i)?'ENTER BATTLE':'VIEW CHALLENGE'}</span></button>`).join('')}</div></section>`;}
function worldEvolution(){const victories=Object.values(state.game.bosses).filter(b=>b.won).length;const stage=victories>=9?3:victories>=4?2:victories>=1?1:0;return `<section class="evolution-panel"><div class="section-caption"><p class="eyebrow">YOUR PROGRESS TRANSFORMS YOUR WORLD</p><h2>Your world evolves</h2></div><div class="evolution-stages">${['The first spark','New foundations','A growing world','More possibilities'].map((label,i)=>`<div class="evolution-stage ${i<=stage?'reached':''}"><span class="evolution-scene scene-${i}" aria-hidden="true"></span><b>${label}</b><small>${[0,1,4,9][i]} worlds conquered ${i===stage?'· YOU ARE HERE':''}</small></div>`).join('')}</div><button class="primary" data-nav="unlocked">Enter UNLOCKED ${icon('KeyRound')}</button></section>`;}

function membershipAdmin(){const cfg=state.billing||{};return `<section class="panel mt"><h2>Automatic PayPal subscriptions</h2><p>Customers subscribe through PayPal. The connected payment server verifies payments and renewals, then updates access. Server setup and a sandbox test are required before launch.</p><form id="billing-settings-form"><label for="billing-api">Payment server HTTPS address</label><input id="billing-api" name="apiUrl" type="url" value="${esc(cfg.apiUrl||'')}" placeholder="https://your-payment-server.example"><label for="offer-label">Subscription button label</label><input id="offer-label" name="offerLabel" maxlength="100" value="${esc(cfg.offerLabel||'Subscribe through PayPal')}" required><label class="answer"><input type="checkbox" name="requireMembership" ${cfg.requireMembership!==false?'checked':''}>Require paid access after world one</label><button class="primary">Save subscription settings</button></form><p class="fine">Pricing and billing frequency come from your PayPal plan. Keep private keys in your server settings. Use Tester access above for free passes.</p><h3>Automatic memberships</h3>${(adminOverview?.automaticMembers||[]).map(m=>`<p><code>${esc(m.id)}</code> · ${esc(m.status)} · ${m.active&&m.expiresAt>Date.now()?'Active':'Inactive / expired'} · ${m.expiresAt?new Date(m.expiresAt).toLocaleString():'No paid period'}</p>`).join('')||'<p>Refresh overview to load automatic memberships.</p>'}<h3>Existing paid access</h3><button class="secondary" data-admin-refresh>Refresh overview</button>${(adminOverview?.members||[]).map(m=>`<p><code>${esc(m.id)}</code> · ${m.active&&m.expiresAt>Date.now()?'Active':'Inactive / expired'} · ${m.expiresAt?new Date(m.expiresAt).toLocaleString():'No access'}</p>`).join('')||'<p>No older owner-reviewed memberships loaded.</p>'}<p>Earlier paid grants remain valid until their saved expiry. New subscriptions use the automatic payment service.</p></section>`;}

function testerAdmin(){return `<section class="panel mt"><p class="eyebrow">PRIVATE · OWNER CONTROLS</p><h2>Tester access</h2><p>Invite testers to create a game account first. Ask for their Player ID from Membership, then grant free access here. Testers follow the normal game progression without needing a PayPal subscription.</p><form id="tester-access-form"><label for="tester-uid">Tester Player ID</label><input id="tester-uid" name="uid" required maxlength="128"><label for="tester-expiry">Access ends (optional, your local time)</label><input id="tester-expiry" name="expiresAt" type="datetime-local"><p class="fine">Leave blank for access until you remove it.</p><label for="tester-note">Tester name / access note (readable by this tester)</label><textarea id="tester-note" name="note" maxlength="500"></textarea><button class="primary" value="grant">Grant / update tester access</button><button class="secondary" value="revoke">Remove tester access</button></form><button class="secondary" data-admin-refresh>Load testers</button><div class="vault-grid">${(adminOverview?.testers||[]).map(t=>`<article class="panel"><b>${esc(t.note||'Tester')}</b><p><code>${esc(t.id)}</code></p><p>${t.active&&(t.expiresAt===0||t.expiresAt>Date.now())?'Active':'Inactive / expired'} · ${t.expiresAt?new Date(t.expiresAt).toLocaleString():'No expiration'}</p><button class="secondary" data-edit-tester="${esc(t.id)}">Manage tester</button></article>`).join('')||'<p>No testers loaded.</p>'}</div><p class="fine">Only the owner can grant or remove tester access. Removing it preserves game progress and any separate paid subscription access.</p></section>`;}
